# REFERENCE: GAMEPLAY-V4.md; RESEARCH-GAMEPLAY-V4.md; NFT-VALUE-SPEC.md.
from pathlib import Path
import base64, hashlib, html, json
root=Path.cwd()
read=lambda p:json.loads((root/p).read_text())
escape=lambda s:html.escape(str(s))
a=read('reports/cardrpg-big/a4/p6/acceptance.json')
catalogue=read('reports/cardrpg-big/a4/p7/guide-data.json')
j=read('reports/cardrpg-big/a4/p7/journey/checks.json')
assert a['artifactSha256']==j['sha256'], 'Guide balance and screenshot artifacts differ'
artifact=root/'docs/cardrpg3/index.html'
sha=hashlib.sha256(artifact.read_bytes()).hexdigest()
assert j['sha256']==sha and j['complete'] and not j['errors']
assert catalogue['artifactSha256']==sha
for file,expected in catalogue['sourceHashes'].items():
 assert hashlib.sha256((root/file).read_bytes()).hexdigest()==expected,file
def shot(name,caption):
 p=root/f'reports/cardrpg-big/a4/p7/journey/{name}.png'
 assert p.is_file(),p
 return '<figure><img loading="lazy" width="1280" height="720" alt="'+escape(caption)+'" src="data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode()+'"><figcaption>'+escape(caption)+'</figcaption></figure>'
def table(head,rows):
 return '<div class="table"><table><thead><tr>'+''.join('<th scope="col">'+escape(x)+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+escape(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
odds_table=table(['Banner','Common','Rare','Epic','Legendary'],[[x['name']]+[f"{x['oddsBp'][r]/100:g}%" for r in ['common','rare','epic','legendary']] for x in catalogue['banners']])
set_table=table(['Set','Two pieces','Four pieces'],[[x['name'],x['two'],x['four']] for x in catalogue['sets']])
item_table=table(['Item','Rarity / shelf cap','Use'],[[x['name'],x['rarity']+' / '+(str(x['cap']) if x['cap']<1000 else 'legacy stack'),x['description']] for x in catalogue['items']])
reward_days=[]
for cohort in a['economy']['distributions']:
 for key,label in [('firstLegendary','First Legendary'),('firstChosen','Chosen reward')]:
  d=cohort[key]
  show=lambda value:str(value) if value is not None else 'Not reached by day 45'
  reward_days.append([cohort['style'],label,show(d['medianDay']),show(d['p90Day']),f"{d['observed']} / {d['accounts']}"])
reward_days_table=table(['Play style','Reward','Median day','90% reached by','Observed by day 45'],reward_days)
sections=[
('<span class="eyebrow">Taskbar Hero · Gameplay v4 preview</span><h1>Build an evening shift.<br>See your choices work.</h1><p class="lead">Collect three cats, prepare a crew, and let an automatic encounter show how their formation, equipment and standing plan work together.</p><a class="button" href="index.html">Open the offline game</a><p class="scope">Local preview. Export your progress from Save &amp; settings before closing, then import the code to continue.</p>'),
'<section id="prepare"><h2>1 · Make a plan before the fight</h2><p>Keep a living front-row cat to cover the rear. Inspect enemy names, rows and the next signature. Choose Finish, Support or Leader focus, then Steady or Protect care. Two distinct cats activate a crew job: two marks give its small effect; four replace it with the full effect.</p><p>During battle, controls are speed, pause, skip and camera. Full unlocked skill kits act automatically; ultimates use a fixed opening delay and cooldown. The result explains observed protection, healing, target choices and gear triggers.</p>'+shot('prepare','Prepare shows enemy pressure, the selected challenge band and your standing plan.')+'</section>',
'<section id="gear"><h2>2 · Build a coherent set</h2><p>Four slots: utensil, apron, clasp and keepsake. Eight sets offer two-piece and four-piece behaviors. Compare a piece in your current build to see stats, thresholds gained or lost, transfers and utility. The power score is an approximate build estimate, not a win probability.</p>'+table(['Rarity','Main-stat multiplier','Role identity'],[['Common','1.00×','One main stat'],['Rare','1.25×','One compatible affix'],['Epic','1.50×','Two compatible affixes'],['Legendary','1.75×','Three affixes and a bounded unique behavior']])+'<p>Enhance up to +12 without a failure roll, reforge one compatible affix, tailor a chosen template, and salvage spare gear. The 240-piece shelf is shared across reward sources. Three saved shifts store crew, rows, plan and exact equipment instances; missing items prevent partial application.</p>'+set_table+'<h3>Pack the pantry between encounters</h3><p>Milk restores missing HP immediately. The other four supplies reserve one item for one companion in the next encounter. Changing or cancelling that reservation returns the unspent item. Prepare it before opening the encounter; there is no in-fight supply button.</p>'+item_table+shot('equipment','Equipment compares what changes in combat before committing a transfer.')+'</section>',
'<section id="invitations"><h2>3 · Earn an invitation, keep a choice</h2><p>Standard, featured and equipment banners use earned stamps: 150 per invitation. The odds drawer is one click away and shows conditional odds for the next pull, including pity. Legendary base chance is 1%; soft pity begins at pull 41 and hard pity guarantees one at 60. A featured miss guarantees the next Legendary is featured.</p>'+odds_table+'<p>These are starting probabilities. The conditional Legendary chance rises by 3 percentage points per pull after 40 draws without one, with a guarantee on draw 60.</p><p>Every paid earned-currency invitation grants one selector mark. Sixty marks choose a companion or eligible gear. The welcome invitation grants no marks. Marks do not expire and choosing a reward does not reset pity. Duplicate companions become shards. There is no purchase button.</p>'+shot('invitations','Earned invitations show odds, pity, duplicates and progress toward a chosen reward.')+'</section>',
'<section id="cafe"><h2>4 · Return to a working cafe</h2><p>Today’s board uses the existing daily and weekly quests. Cafe service accrues from elapsed time, allows two services per UTC day and counts at most eight hours away. Skipped dates do not stack rewards. A clock watermark prevents rollback claims.</p><p>The collection journal remembers first ownership after salvage, completed sets and rewarded routes. Milestones can be claimed once; a full daily allowance preserves a pending claim. One ordered lesson at a time introduces the next system, and returning players can move on.</p>'+shot('cafe-hour','One elapsed test hour: claim service, inspect today’s board and choose the next action.')+shot('journal','The persistent journal shows milestones and capped rewards before you claim.')+'</section>',
'<section id="routes"><h2>5 · Choose your next table</h2><p>Three chapters offer routes with ordinary battles, elites, events, shops, treasures and campfires. Route points pay for temporary rewards; a campfire restores the crew. Between encounters, compare the next opponents with your remaining HP and packed supply. Daily challenge and Tower add alternate routes, with progress shown at the cafe.</p><p>A route locks its challenge band when it starts. Enemies do not become stronger just because you equip an item. Bosses change phase once at half HP. When the boss falls, its linked helpers leave at the action boundary. Read the result observations to see which shields, heals and target choices mattered.</p></section>',
'<section id="limits"><h2>6 · Know what is scarce</h2>'+table(['Resource','Repeatable daily limit','Examples of uses'],[['Fish','420','Levels, crafting, enhancement'],['Threads','90','Crafting, enhancement, reforge'],['Stamps','180; at most 30 invitations','Earned invitations'],['Essence','6','Awakening and recipes'],['Selector marks','30 from paid invitations','60 for a chosen reward']])+'<p>One-time progression rewards and recycling owned items are disclosed separately. Ordinary equipment is account-bound, including its keepsake slot.</p>'+table(['Design','Lifetime / season cap','Effort and account limit'],[['Moon Collar','2,400 / 400','3 spent boss-day seals and chapter one'],['Golden Maneki','360 / 60','10 spent seals and all chapter masteries or Tower 5']])+'<p>At most one reservation per account, edition and season, and one reservation per UTC day. Burns never reopen supply; two Moon records from different seasons can become a cosmetic badge. Editions add zero combat stats.</p><p><strong>Design only — not minted.</strong> The replayable issuance ledger enforces limits within this local save. It is not global enforcement across copied saves. The existing Fuji Relic bridge remains separate; no on-chain launch is included.</p>'+shot('collectibles','The local authority preview shows caps, effort still needed and reservation records.')+'</section>',
'<section id="evidence"><h2>7 · What the measurements say</h2><p>Training and heldout seeds are separate. Each acceptance cell uses at least 500 seeds; the economy follows 30 accounts per play style for 45 synthetic days. These are automated simulations and scripted clicks, not independent human playtests.</p>'+table(['Target','Before','After','Status'],a['rows'])+'<p>Misses remain visible. Controlled matched-power fixtures are distinct from earned new-save progression. The game labels power as approximate, and the detailed reports preserve seed outcomes, confidence intervals, failures and source hashes.</p><ul><li><a href="../../reports/cardrpg-big/a4/P6-BALANCE.md">Balance methods and results</a></li><li><a href="../../reports/cardrpg-big/a4/A4-GAMEPLAY-REPORT.md">Gameplay delivery report</a></li><li><a href="../design/cardrpg/GAMEPLAY-V4.md">Gameplay specification</a></li><li><a href="../design/cardrpg/RESEARCH-GAMEPLAY-V4.md">Research and design rationale</a></li><li><a href="../design/cardrpg/NFT-VALUE-SPEC.md">Future collectible boundary</a></li></ul></section>',
'<section id="earned-rewards"><h2>8 · How long the earned route takes</h2><p>Each play style follows 30 new accounts for 45 simulated days. Median and 90% milestones count every account, including those still waiting. These earned-day observations are separate from controlled draw-count odds tests.</p>'+reward_days_table+'<p>“Not reached by day 45” leaves the waiting time unknown beyond the observation window. It is not a prediction of when the reward will arrive.</p></section>',
'<footer><p>Game artifact: '+escape(f'{artifact.stat().st_size:,} bytes')+'</p><p class="hash">SHA-256 '+sha+'</p><p>All screenshots come from this artifact. Gameplay v4 is enabled in the offline demo; live defaults are unchanged.</p></footer>'
]
css='''*{box-sizing:border-box}html{color-scheme:light;scroll-behavior:smooth}body{margin:0;background:#f5efdf;color:#203334;font:17px/1.7 system-ui,sans-serif}main{max-width:1100px;margin:auto;padding:64px 36px}h1,h2{font-family:Georgia,serif;line-height:1.18}h1{font-size:clamp(40px,5vw,72px);margin:18px 0}h2{font-size:34px}p{max-width:80ch}.eyebrow{font-size:14px;letter-spacing:.13em;text-transform:uppercase}.lead{font-size:23px}.button{display:inline-block;padding:12px 24px;color:#fff9e9;background:#203334;border-radius:8px;text-decoration:none}.button:focus-visible,a:focus-visible{outline:3px solid #89520e;outline-offset:4px}section{padding-top:50px;margin-top:38px;border-top:1px solid #9e997f}a{color:#354b75}figure{margin:28px 0}img{display:block;width:100%;height:auto;border:1px solid #9e997f;border-radius:8px}figcaption,.scope{font-size:14px;color:#45514d}.table{overflow-x:auto}table{width:100%;border-collapse:collapse;font-size:15px}th,td{text-align:left;border-bottom:1px solid #b9b09b;padding:12px;vertical-align:top}th{background:#e6ddc5}footer{margin-top:60px;font-size:13px}.hash{overflow-wrap:anywhere}@media(max-width:700px){main{padding:32px 20px}h2{font-size:28px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}'''
result='<!-- REFERENCE: docs/design/cardrpg/GAMEPLAY-V4.md; docs/design/cardrpg/RESEARCH-GAMEPLAY-V4.md; docs/design/cardrpg/NFT-VALUE-SPEC.md -->\n<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Taskbar Hero · Gameplay v4</title><style>'+css+'</style><main>'+''.join(sections)+'</main></html>'
out=root/'docs/cardrpg3/gameplay-v4.html';out.write_text(result)
print(json.dumps({'path':str(out),'bytes':out.stat().st_size,'sha256':hashlib.sha256(out.read_bytes()).hexdigest(),'gameArtifactSha256':sha}))
